TECH_SPEC_HTML = '<!DOCTYPE html>\n<html lang="pt-BR">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>SC3 DocAudit — Especificação Técnica & Motor Forense</title>\n    <meta name="description" content="Especificação técnica detalhada, algoritmos de visão computacional, calibração de incerteza, segurança criptográfica forense e roadmap do SC3 DocAudit.">\n    <link rel="preconnect" href="https://fonts.googleapis.com">\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n    <link href="https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;600;700&family=Outfit:wght@400;600;700;800&family=Plus+Jakarta+Sans:wght@300;400;500;600;700&display=swap" rel="stylesheet">\n    <style>\n        :root {\n            --bg-primary: #090d16;\n            --bg-card: rgba(18, 24, 38, 0.75);\n            --bg-card-hover: rgba(26, 35, 56, 0.85);\n            --border-color: rgba(255, 255, 255, 0.08);\n            --border-accent: rgba(0, 245, 155, 0.3);\n            --emerald: #00f59b;\n            --emerald-glow: rgba(0, 245, 155, 0.2);\n            --teal: #0ea5e9;\n            --amber: #f59e0b;\n            --rose: #f43f5e;\n            --text-main: #f1f5f9;\n            --text-muted: #94a3b8;\n            --font-main: \'Plus Jakarta Sans\', -apple-system, BlinkMacSystemFont, sans-serif;\n            --font-heading: \'Outfit\', sans-serif;\n            --font-mono: \'JetBrains Mono\', monospace;\n        }\n\n        * {\n            box-sizing: border-box;\n            margin: 0;\n            padding: 0;\n        }\n\n        body {\n            background-color: var(--bg-primary);\n            color: var(--text-main);\n            font-family: var(--font-main);\n            line-height: 1.6;\n            overflow-x: hidden;\n            background-image: \n                radial-gradient(circle at 10% 20%, rgba(0, 245, 155, 0.05) 0%, transparent 40%),\n                radial-gradient(circle at 90% 80%, rgba(14, 165, 233, 0.05) 0%, transparent 40%);\n            background-attachment: fixed;\n        }\n\n        header {\n            border-bottom: 1px solid var(--border-color);\n            backdrop-filter: blur(16px);\n            background: rgba(9, 13, 22, 0.8);\n            position: sticky;\n            top: 0;\n            z-index: 100;\n        }\n\n        .nav-container {\n            max-width: 1280px;\n            margin: 0 auto;\n            padding: 1rem 2rem;\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n        }\n\n        .logo-area {\n            display: flex;\n            align-items: center;\n            gap: 0.75rem;\n            text-decoration: none;\n            color: var(--text-main);\n        }\n\n        .logo-badge {\n            background: linear-gradient(135deg, var(--emerald), var(--teal));\n            color: #051410;\n            font-weight: 800;\n            font-size: 0.9rem;\n            padding: 0.35rem 0.65rem;\n            border-radius: 8px;\n            box-shadow: 0 0 16px var(--emerald-glow);\n        }\n\n        .logo-title {\n            font-family: var(--font-heading);\n            font-weight: 700;\n            font-size: 1.25rem;\n            letter-spacing: -0.02em;\n        }\n\n        .nav-links {\n            display: flex;\n            gap: 1.5rem;\n            align-items: center;\n        }\n\n        .nav-link {\n            color: var(--text-muted);\n            text-decoration: none;\n            font-size: 0.9rem;\n            font-weight: 500;\n            transition: all 0.2s ease;\n        }\n\n        .nav-link:hover {\n            color: var(--emerald);\n        }\n\n        .btn-github {\n            background: rgba(255, 255, 255, 0.06);\n            border: 1px solid var(--border-color);\n            color: var(--text-main);\n            padding: 0.45rem 1rem;\n            border-radius: 8px;\n            text-decoration: none;\n            font-size: 0.85rem;\n            font-weight: 600;\n            display: flex;\n            align-items: center;\n            gap: 0.5rem;\n            transition: all 0.2s;\n        }\n\n        .btn-github:hover {\n            border-color: var(--emerald);\n            box-shadow: 0 0 12px var(--emerald-glow);\n        }\n\n        .container {\n            max-width: 1200px;\n            margin: 0 auto;\n            padding: 3rem 1.5rem 6rem;\n        }\n\n        .hero {\n            text-align: center;\n            margin-bottom: 4rem;\n        }\n\n        .hero-tag {\n            display: inline-flex;\n            align-items: center;\n            gap: 0.5rem;\n            background: rgba(0, 245, 155, 0.1);\n            border: 1px solid var(--border-accent);\n            color: var(--emerald);\n            padding: 0.35rem 1rem;\n            border-radius: 9999px;\n            font-size: 0.85rem;\n            font-weight: 600;\n            margin-bottom: 1.25rem;\n        }\n\n        h1 {\n            font-family: var(--font-heading);\n            font-size: 2.75rem;\n            font-weight: 800;\n            line-height: 1.2;\n            letter-spacing: -0.03em;\n            margin-bottom: 1rem;\n            background: linear-gradient(135deg, #ffffff 40%, var(--emerald) 100%);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n        }\n\n        .hero-desc {\n            max-width: 780px;\n            margin: 0 auto 2rem;\n            color: var(--text-muted);\n            font-size: 1.15rem;\n        }\n\n        .badges-bar {\n            display: flex;\n            justify-content: center;\n            flex-wrap: wrap;\n            gap: 0.75rem;\n            margin-bottom: 2rem;\n        }\n\n        .badge-item {\n            background: rgba(255, 255, 255, 0.04);\n            border: 1px solid var(--border-color);\n            padding: 0.4rem 0.85rem;\n            border-radius: 6px;\n            font-size: 0.8rem;\n            font-family: var(--font-mono);\n            color: var(--text-muted);\n        }\n\n        .badge-item span {\n            color: var(--emerald);\n            font-weight: 700;\n        }\n\n        .grid-2 {\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(360px, 1fr));\n            gap: 1.75rem;\n            margin-bottom: 3rem;\n        }\n\n        .grid-3 {\n            display: grid;\n            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\n            gap: 1.5rem;\n            margin-bottom: 3rem;\n        }\n\n        .card {\n            background: var(--bg-card);\n            border: 1px solid var(--border-color);\n            border-radius: 16px;\n            padding: 2rem;\n            backdrop-filter: blur(12px);\n            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);\n            position: relative;\n            overflow: hidden;\n        }\n\n        .card:hover {\n            border-color: var(--border-accent);\n            transform: translateY(-3px);\n            box-shadow: 0 12px 30px rgba(0, 0, 0, 0.4), 0 0 20px var(--emerald-glow);\n        }\n\n        .card-header {\n            display: flex;\n            align-items: center;\n            gap: 0.85rem;\n            margin-bottom: 1.25rem;\n        }\n\n        .card-icon {\n            width: 44px;\n            height: 44px;\n            border-radius: 10px;\n            background: rgba(0, 245, 155, 0.1);\n            border: 1px solid var(--border-accent);\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            font-size: 1.35rem;\n        }\n\n        h2, h3 {\n            font-family: var(--font-heading);\n            letter-spacing: -0.02em;\n        }\n\n        h2 {\n            font-size: 1.85rem;\n            margin-bottom: 1rem;\n            color: #ffffff;\n        }\n\n        h3 {\n            font-size: 1.3rem;\n            color: #ffffff;\n        }\n\n        p {\n            color: var(--text-muted);\n            font-size: 0.95rem;\n            margin-bottom: 1rem;\n        }\n\n        ul {\n            list-style: none;\n            margin-bottom: 1.25rem;\n        }\n\n        li {\n            color: var(--text-muted);\n            font-size: 0.92rem;\n            margin-bottom: 0.6rem;\n            display: flex;\n            align-items: flex-start;\n            gap: 0.5rem;\n        }\n\n        li::before {\n            content: "▹";\n            color: var(--emerald);\n            font-weight: bold;\n        }\n\n        .code-block {\n            background: rgba(0, 0, 0, 0.45);\n            border: 1px solid rgba(255, 255, 255, 0.05);\n            border-radius: 8px;\n            padding: 1rem;\n            font-family: var(--font-mono);\n            font-size: 0.85rem;\n            color: #38bdf8;\n            overflow-x: auto;\n            margin: 1rem 0;\n            line-height: 1.5;\n        }\n\n        .formula-box {\n            background: rgba(0, 245, 155, 0.04);\n            border: 1px dashed var(--border-accent);\n            border-radius: 10px;\n            padding: 1.25rem;\n            text-align: center;\n            font-family: var(--font-mono);\n            font-size: 1rem;\n            color: var(--emerald);\n            margin: 1.25rem 0;\n        }\n\n        /* Interactive Forensics Simulator */\n        .interactive-panel {\n            background: rgba(14, 20, 32, 0.9);\n            border: 1px solid var(--border-accent);\n            border-radius: 16px;\n            padding: 2.25rem;\n            margin: 3.5rem 0;\n            box-shadow: 0 0 35px rgba(0, 245, 155, 0.08);\n        }\n\n        .panel-title {\n            display: flex;\n            align-items: center;\n            gap: 0.75rem;\n            font-size: 1.5rem;\n            margin-bottom: 0.5rem;\n            color: #ffffff;\n        }\n\n        .input-group {\n            margin-bottom: 1.25rem;\n        }\n\n        .input-label {\n            display: block;\n            font-size: 0.85rem;\n            font-weight: 600;\n            color: var(--text-main);\n            margin-bottom: 0.4rem;\n            text-transform: uppercase;\n            letter-spacing: 0.05em;\n        }\n\n        .input-field {\n            width: 100%;\n            background: rgba(0, 0, 0, 0.5);\n            border: 1px solid var(--border-color);\n            border-radius: 8px;\n            padding: 0.75rem 1rem;\n            color: #ffffff;\n            font-family: var(--font-mono);\n            font-size: 0.9rem;\n            transition: border-color 0.2s;\n        }\n\n        .input-field:focus {\n            outline: none;\n            border-color: var(--emerald);\n        }\n\n        .merkle-tree-visual {\n            background: rgba(0, 0, 0, 0.6);\n            border-radius: 12px;\n            padding: 1.5rem;\n            margin-top: 1.5rem;\n            border: 1px solid rgba(255, 255, 255, 0.05);\n        }\n\n        .tree-node {\n            background: rgba(255, 255, 255, 0.04);\n            border: 1px solid var(--border-color);\n            border-radius: 8px;\n            padding: 0.75rem;\n            margin: 0.5rem 0;\n            font-family: var(--font-mono);\n            font-size: 0.85rem;\n            word-break: break-all;\n        }\n\n        .tree-node.root {\n            border-color: var(--emerald);\n            background: rgba(0, 245, 155, 0.08);\n            color: var(--emerald);\n            font-weight: 700;\n        }\n\n        .tree-node.leaf {\n            border-color: var(--teal);\n            background: rgba(14, 165, 233, 0.06);\n            color: #7dd3fc;\n        }\n\n        /* Roadmap Checklist */\n        .checklist-item {\n            display: flex;\n            align-items: flex-start;\n            gap: 1rem;\n            background: rgba(255, 255, 255, 0.03);\n            border: 1px solid var(--border-color);\n            border-radius: 10px;\n            padding: 1rem 1.25rem;\n            margin-bottom: 0.85rem;\n            transition: all 0.2s;\n        }\n\n        .checklist-item:hover {\n            background: rgba(255, 255, 255, 0.05);\n            border-color: rgba(0, 245, 155, 0.2);\n        }\n\n        .checklist-status {\n            font-size: 1.1rem;\n            flex-shrink: 0;\n            margin-top: 2px;\n        }\n\n        .checklist-content h4 {\n            font-size: 1rem;\n            color: #ffffff;\n            margin-bottom: 0.25rem;\n        }\n\n        .checklist-content p {\n            margin-bottom: 0;\n            font-size: 0.85rem;\n        }\n\n        .tag-phase {\n            display: inline-block;\n            font-size: 0.7rem;\n            font-weight: 700;\n            padding: 0.2rem 0.5rem;\n            border-radius: 4px;\n            margin-left: 0.5rem;\n            text-transform: uppercase;\n        }\n\n        .phase-done { background: rgba(0, 245, 155, 0.15); color: var(--emerald); }\n        .phase-q1 { background: rgba(14, 165, 233, 0.15); color: var(--teal); }\n        .phase-q2 { background: rgba(245, 158, 11, 0.15); color: var(--amber); }\n\n        footer {\n            border-top: 1px solid var(--border-color);\n            padding: 3rem 1.5rem;\n            text-align: center;\n            color: var(--text-muted);\n            font-size: 0.9rem;\n        }\n\n        .footer-links {\n            display: flex;\n            justify-content: center;\n            gap: 1.5rem;\n            margin-bottom: 1.5rem;\n        }\n\n        .footer-links a {\n            color: var(--emerald);\n            text-decoration: none;\n        }\n\n        .footer-links a:hover {\n            text-decoration: underline;\n        }\n\n        /* Slider Controls */\n        .slider-container {\n            display: grid;\n            grid-template-columns: 1fr auto;\n            align-items: center;\n            gap: 1rem;\n            margin-bottom: 1rem;\n        }\n\n        .slider-input {\n            -webkit-appearance: none;\n            width: 100%;\n            height: 6px;\n            border-radius: 3px;\n            background: rgba(255, 255, 255, 0.1);\n            outline: none;\n        }\n\n        .slider-input::-webkit-slider-thumb {\n            -webkit-appearance: none;\n            appearance: none;\n            width: 18px;\n            height: 18px;\n            border-radius: 50%;\n            background: var(--emerald);\n            cursor: pointer;\n            box-shadow: 0 0 10px var(--emerald);\n        }\n\n        .score-display {\n            font-family: var(--font-mono);\n            font-size: 1.5rem;\n            font-weight: 700;\n            padding: 0.75rem 1.5rem;\n            border-radius: 10px;\n            text-align: center;\n            margin-top: 1rem;\n        }\n\n        .score-pass {\n            background: rgba(0, 245, 155, 0.1);\n            border: 1px solid var(--emerald);\n            color: var(--emerald);\n        }\n\n        .score-null {\n            background: rgba(244, 63, 94, 0.1);\n            border: 1px solid var(--rose);\n            color: var(--rose);\n        }\n    </style>\n</head>\n<body>\n\n    <header>\n        <div class="nav-container">\n            <a href="/" class="logo-area">\n                <span class="logo-badge">SC3 PROTOCOL</span>\n                <span class="logo-title">DocAudit Engine</span>\n            </a>\n            <div class="nav-links">\n                <a href="/" class="nav-link" style="color:var(--emerald);font-weight:700;">⬅️ Voltar ao Painel</a>\n                <a href="#vision" class="nav-link">Visão Computacional</a>\n                <a href="#confidence" class="nav-link">Calibração</a>\n                <a href="#crypto" class="nav-link">Criptografia CPP</a>\n                <a href="#simulator" class="nav-link">Simulador Merkle</a>\n                <a href="#roadmap" class="nav-link">Roadmap</a>\n                <a href="https://github.com/Raoni1984/amazoniahackathon_s3c_docaudit" target="_blank" class="btn-github">\n                    <svg width="16" height="16" fill="currentColor" viewBox="0 0 24 24"><path d="M12 0C5.37 0 0 5.37 0 12c0 5.31 3.435 9.795 8.205 11.385.6.105.825-.255.825-.57 0-.285-.015-1.23-.015-2.235-3.015.555-3.795-.735-4.035-1.41-.135-.345-.72-1.41-1.23-1.695-.42-.225-1.02-.78-.015-.795.945-.015 1.62.87 1.845 1.23 1.08 1.815 2.805 1.305 3.495.99.105-.78.42-1.305.765-1.605-2.67-.3-5.46-1.335-5.46-5.925 0-1.305.465-2.385 1.23-3.225-.12-.3-.54-1.53.12-3.18 0 0 1.005-.315 3.3 1.23.96-.27 1.98-.405 3-.405s2.04.135 3 .405c2.295-1.56 3.3-1.23 3.3-1.23.66 1.65.24 2.88.12 3.18.765.84 1.23 1.905 1.23 3.225 0 4.605-2.805 5.625-5.475 5.925.435.375.81 1.095.81 2.22 0 1.605-.015 2.895-.015 3.3 0 .315.225.69.825.57A12.02 12.02 0 0024 12c0-6.63-5.37-12-12-12z"/></svg>\n                    GitHub\n                </a>\n            </div>\n        </div>\n    </header>\n\n    <div class="container">\n\n        <div class="hero">\n            <div class="hero-tag">\n                <span>⚡ AmazoniaHack 4.0 Technical Specification</span>\n            </div>\n            <h1>Especificação Técnica & Motor Forense</h1>\n            <p class="hero-desc">\n                Como o <strong>SC3 DocAudit</strong> transforma imagens de autos físicos e logs de GPS em provas periciais inalteráveis e matematicamente auditáveis nos Tribunais (Arts. 158-A a 158-F do CPP).\n            </p>\n            <div class="badges-bar">\n                <div class="badge-item">Arquitetura: <span>Occurrence-First (1:N)</span></div>\n                <div class="badge-item">Resistência de Colisão: <span>2²⁵⁶ (SHA-256)</span></div>\n                <div class="badge-item">Anti-Alucinação: <span>Score < 0.35 → null</span></div>\n                <div class="badge-item">Confiabilidade Testes: <span>17/17 Passing (100%)</span></div>\n            </div>\n        </div>\n\n        <!-- Seção 1: Visão Computacional -->\n        <div id="vision" class="card" style="margin-bottom: 2.5rem;">\n            <div class="card-header">\n                <div class="card-icon">👁️</div>\n                <div>\n                    <h2>1. Pipeline de Visão Computacional & Pré-Processamento</h2>\n                    <p style="margin: 0;">Módulo: <code>sc3_docaudit/core/image_preprocessing.py</code></p>\n                </div>\n            </div>\n            <p>\n                Em operações reais de fiscalização, os autos de infração são fotografados em pranchetas e suportes de campo em viaturas sob iluminação desuniforme da copa da floresta, com papel carbono desgastado e ângulos inclinados. O motor aplica uma esteira determinística de 4 estágios:\n            </p>\n\n            <div class="grid-2">\n                <div>\n                    <h3>Etapas Algorítmicas</h3>\n                    <ul>\n                        <li><strong>Retângulo de Área Mínima (cv2.minAreaRect)</strong>: Calcula os momentos da maior componente conexa do papel para estimar o ângulo de rotação ($\\theta$) e aplica matrizes afins para retificação geométrica (<em>deskew</em>).</li>\n                        <li><strong>CLAHE (Equalização Adaptativa de Histograma)</strong>: Normaliza a distribuição de luminância em blocos locais ($8 \\times 8$), eliminando sombras severas de árvores e dedos sem queimar o contraste do texto.</li>\n                        <li><strong>Binarização Adaptativa de Otsu & Gaussiana</strong>: Segmenta traços finos de papel carbono e impressoras matriciais antigas com limiarização dinâmica.</li>\n                        <li><strong>Filtro Bilateral</strong>: Suprime ruídos de sensor da câmera preservando estritamente as arestas vivas dos caracteres manuscritos.</li>\n                    </ul>\n                </div>\n                <div>\n                    <h3>Implementação Determinística</h3>\n                    <div class="code-block">\n# Pipeline determinístico sem perda de dados\ngray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)\ndenoised = cv2.bilateralFilter(gray, 9, 75, 75)\nclahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8,8))\nenhanced = clahe.apply(denoised)\nthresh = cv2.adaptiveThreshold(enhanced, 255, \n    cv2.ADAPTIVE_THRESH_GAUSSIAN_C, \n    cv2.THRESH_BINARY, 11, 2)\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <!-- Seção 2: Calibração de Confiança -->\n        <div id="confidence" class="card" style="margin-bottom: 2.5rem;">\n            <div class="card-header">\n                <div class="card-icon">🎯</div>\n                <div>\n                    <h2>2. Calibração Multidimensional & Política Anti-Alucinação</h2>\n                    <p style="margin: 0;">Módulo: <code>sc3_docaudit/core/confidence_evaluator.py</code></p>\n                </div>\n            </div>\n            <p>\n                Diferente de modelos puramente generativos que inventam dados plausíveis quando encontram trechos ilegíveis, o SC3 DocAudit implementa <strong>calibração estocástica estrita</strong>. Se a evidência é ilegível, o campo é explicitamente marcado como <code>null</code>.\n            </p>\n\n            <div class="formula-box">\n                Confidence(x) = min(1.0, max(0.0, 0.45 · P_OCR + 0.35 · V_Syntax + 0.20 · A_Spatial))\n            </div>\n\n            <div class="grid-3">\n                <div class="card" style="padding: 1.25rem;">\n                    <h3>P_OCR (45%)</h3>\n                    <p>Probabilidade bayesiana das caixas delimitadoras da rede neural EasyOCR/CRNN.</p>\n                </div>\n                <div class="card" style="padding: 1.25rem;">\n                    <h3>V_Syntax (35%)</h3>\n                    <p>Validação por máscaras RegEx (ex.: CAR <code>PA-1500602-...</code> pontua $0.95$, datas válidas pontuam $0.90$).</p>\n                </div>\n                <div class="card" style="padding: 1.25rem;">\n                    <h3>A_Spatial (20%)</h3>\n                    <p>Consistência geográfica dentro da Amazônia Legal (Lat: -15° a +5°, Lon: -74° a -44°).</p>\n                </div>\n            </div>\n\n            <div style="background: rgba(244, 63, 94, 0.08); border: 1px solid var(--rose); border-radius: 10px; padding: 1rem 1.5rem;">\n                <strong style="color: var(--rose);">🛡️ Regra de Ouro (Zero-Hallucination Threshold):</strong>\n                <p style="margin: 0.25rem 0 0; font-size: 0.9rem;">\n                    Se $\\text{Confidence} < 0.35$, o extrator aborta a predição, grava <code>null</code> e aciona o flag de intervenção humana (<em>Human-in-the-Loop</em>).\n                </p>\n            </div>\n        </div>\n\n        <!-- Seção 3: Simulador Interativo de Calibração -->\n        <div class="interactive-panel">\n            <div class="panel-title">\n                <span>🎛️</span>\n                <h3>Simulador Interativo de Anti-Alucinação</h3>\n            </div>\n            <p>Ajuste os fatores abaixo para testar a decisão em tempo real do motor de calibração:</p>\n\n            <div class="slider-container">\n                <div>\n                    <label class="input-label">P_OCR (Probabilidade Bayesiana do OCR)</label>\n                    <input type="range" min="0" max="100" value="75" class="slider-input" id="ocrSlider" oninput="updateConfidenceSim()">\n                </div>\n                <span id="ocrVal" style="font-family: var(--font-mono); font-weight: 700; color: var(--emerald);">0.75</span>\n            </div>\n\n            <div class="slider-container">\n                <div>\n                    <label class="input-label">V_Syntax (Validação de Máscara / Sintaxe)</label>\n                    <input type="range" min="0" max="100" value="90" class="slider-input" id="syntaxSlider" oninput="updateConfidenceSim()">\n                </div>\n                <span id="syntaxVal" style="font-family: var(--font-mono); font-weight: 700; color: var(--emerald);">0.90</span>\n            </div>\n\n            <div class="slider-container">\n                <div>\n                    <label class="input-label">A_Spatial (Consistência Territorial Amazônica)</label>\n                    <input type="range" min="0" max="100" value="80" class="slider-input" id="spatialSlider" oninput="updateConfidenceSim()">\n                </div>\n                <span id="spatialVal" style="font-family: var(--font-mono); font-weight: 700; color: var(--emerald);">0.80</span>\n            </div>\n\n            <div id="scoreBox" class="score-display score-pass">\n                Score Calculado: <span id="finalScore">0.81</span> — <span id="verdict">CAMPO EXTRAÍDO COM SUCESSO</span>\n            </div>\n        </div>\n\n        <!-- Seção 4: Segurança Criptográfica & Arts. 158-A/F CPP -->\n        <div id="crypto" class="card" style="margin-bottom: 2.5rem;">\n            <div class="card-header">\n                <div class="card-icon">🛡️</div>\n                <div>\n                    <h2>3. Cadeia de Custódia Criptográfica & Validade Forense (CPP)</h2>\n                    <p style="margin: 0;">Módulos: <code>sc3_docaudit/core/crypto_seal.py</code> & <code>reconciler.py</code></p>\n                </div>\n            </div>\n            <p>\n                A quebra na cadeia de custódia é o principal argumento jurídico para anulação de autos ambientais. O <strong>Protocolo SC3</strong> implementa o "Lacre Matemático" que atende diretamente aos requisitos da Lei nº 13.964/2019 (Pacote Anticrime):\n            </p>\n\n            <div class="grid-2">\n                <div>\n                    <h3>Conformidade Estrita com o CPP</h3>\n                    <ul>\n                        <li><strong>Art. 158-A (Definição de Cadeia de Custódia)</strong>: Rastreia a história cronológica de todas as folhas físicas, fotos georreferenciadas e áudios de campo.</li>\n                        <li><strong>Art. 158-B (Etapas de Fixação e Acondicionamento)</strong>: No momento da apreensão, o hash SHA-256 é calculado localmente no dispositivo e imutabilizado na SQLite.</li>\n                        <li><strong>Princípio da "Mesmidade da Prova" (STJ)</strong>: O Tribunal ou Perito Judicial pode rodar <code>sha256sum</code> ou <code>certutil</code> no terminal e confirmar que o arquivo apresentado em juízo é bit-a-bit idêntico ao coletado na floresta.</li>\n                        <li><strong>Resistência de Colisão ($2^{256}$)</strong>: Seriam necessários mais computadores do que átomos no universo observável rodando por bilhões de anos para forjar uma colisão SHA-256.</li>\n                    </ul>\n                </div>\n                <div>\n                    <h3>Árvore de Merkle Binária</h3>\n                    <div class="code-block">\n                  [ Merkle Root Hash ]\n                           /      \\\n            [ H(Doc + Metadados) ]  [ H(Fotos + Áudios) ]\n                 /            \\           /          \\\n            H(Auto.jpg)    H(JSON)   H(Audio.mp3)  H(GPS.gpx)\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <!-- Seção 5: Simulador de Árvore de Merkle em JS -->\n        <div id="simulator" class="interactive-panel">\n            <div class="panel-title">\n                <span>🌳</span>\n                <h3>Simulador Forense de Árvore de Merkle (SHA-256 em Tempo Real)</h3>\n            </div>\n            <p>Edite os dados de campo abaixo para ver o cálculo da Raiz de Merkle acontecer ao vivo usando a Web Cryptography API do seu navegador:</p>\n\n            <div class="grid-2">\n                <div class="input-group">\n                    <label class="input-label">Folha de Evidência 1 (Auto de Infração)</label>\n                    <input type="text" id="leaf1" class="input-field" value="AUTO-INFRACAO-1049-NOVO-PROGRESSO-PA" oninput="calculateLiveMerkle()">\n                </div>\n                <div class="input-group">\n                    <label class="input-label">Folha de Evidência 2 (Extrato JSON Estruturado)</label>\n                    <input type="text" id="leaf2" class="input-field" value="AREA_HA:145.2;VALOR_MULTA:350000.00;CAR:PA-1500602" oninput="calculateLiveMerkle()">\n                </div>\n                <div class="input-group">\n                    <label class="input-label">Folha de Evidência 3 (Foto de Campo / Metadados EXIF)</label>\n                    <input type="text" id="leaf3" class="input-field" value="LAT:-07.1245;LON:-55.4312;TIMESTAMP:2026-09-15T14:30:00Z" oninput="calculateLiveMerkle()">\n                </div>\n                <div class="input-group">\n                    <label class="input-label">Folha de Evidência 4 (Gravação de Voz do Fiscal)</label>\n                    <input type="text" id="leaf4" class="input-field" value="AUDIO_NOTE:Desmatamento recente constatado na coordenada 07 Sul" oninput="calculateLiveMerkle()">\n                </div>\n            </div>\n\n            <div class="merkle-tree-visual">\n                <div class="input-label" style="color: var(--emerald);">🌿 Raiz de Merkle Criptografada (Lacre SC3):</div>\n                <div id="rootNode" class="tree-node root">Calculando...</div>\n\n                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem; margin-top: 1rem;">\n                    <div>\n                        <div class="input-label" style="color: var(--teal);">Nó Intermediário H(1,2):</div>\n                        <div id="node12" class="tree-node leaf">...</div>\n                    </div>\n                    <div>\n                        <div class="input-label" style="color: var(--teal);">Nó Intermediário H(3,4):</div>\n                        <div id="node34" class="tree-node leaf">...</div>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <!-- Seção 6: Roadmap & Features Checklist -->\n        <div id="roadmap" class="card">\n            <div class="card-header">\n                <div class="card-icon">🚀</div>\n                <div>\n                    <h2>4. Checklist de Próximas Features & Roadmap Aberto</h2>\n                    <p style="margin: 0;">Perspectivas de evolução para a comunidade Open Source</p>\n                </div>\n            </div>\n\n            <div class="checklist-item">\n                <div class="checklist-status">✅</div>\n                <div class="checklist-content">\n                    <h4>Motor de Extração Offline & Calibração de Incerteza <span class="tag-phase phase-done">Concluído (Hackathon 4.0)</span></h4>\n                    <p>Extração agnóstica a layouts com binarização adaptativa, deskew automático e calibração multidimensional contra alucinações.</p>\n                </div>\n            </div>\n\n            <div class="checklist-item">\n                <div class="checklist-status">✅</div>\n                <div class="checklist-content">\n                    <h4>Cadeia de Custódia SC3 com Árvore de Merkle SHA-256 <span class="tag-phase phase-done">Concluído (Hackathon 4.0)</span></h4>\n                    <p>Amarração probatória de imagens, áudios e JSONs com exportação em container autônomo <code>.sc3</code> e auditoria 100% via terminal.</p>\n                </div>\n            </div>\n\n            <div class="checklist-item">\n                <div class="checklist-status">🔄</div>\n                <div class="checklist-content">\n                    <h4>Assinatura Digital dos Agentes via Chaves Ed25519 / ICP-Brasil <span class="tag-phase phase-q1">Q4 2026</span></h4>\n                    <p>Incorporar pares de chaves assimétricas criptográficas diretamente no hardware do fiscal para aposição de fé pública digital sobre a Raiz de Merkle.</p>\n                </div>\n            </div>\n\n            <div class="checklist-item">\n                <div class="checklist-status">🔄</div>\n                <div class="checklist-content">\n                    <h4>Detector de Documentos Leve com YOLOv8-Nano On-Device <span class="tag-phase phase-q1">Q4 2026</span></h4>\n                    <p>Segmentação automática das bordas do papel em tempo real na tela do celular antes do disparo fotográfico, eliminando 100% do ruído de fundo.</p>\n                </div>\n            </div>\n\n            <div class="checklist-item">\n                <div class="checklist-status">⏳</div>\n                <div class="checklist-content">\n                    <h4>RAG Jurídico Offline para Enquadramento do Decreto 6.514/2008 <span class="tag-phase phase-q2">Q1 2027</span></h4>\n                    <p>Base vetorial SQLite embarcada com toda a legislação ambiental brasileira para sugestão automática dos artigos infringidos com base no relato de campo.</p>\n                </div>\n            </div>\n\n            <div class="checklist-item">\n                <div class="checklist-status">⏳</div>\n                <div class="checklist-content">\n                    <h4>Sincronização P2P Wi-Fi Direct em Malha (Mesh) entre Fiscais <span class="tag-phase phase-q2">Q1 2027</span></h4>\n                    <p>Permitir que diferentes equipes em campo troquem dossiês e boletins de ocorrência diretamente via rádio/Wi-Fi sem depender de nenhuma torre central.</p>\n                </div>\n            </div>\n        </div>\n\n    </div>\n\n    <footer>\n        <div class="footer-links">\n            <a href="https://amazoniahack.co/" target="_blank">Portal Oficial AmazoniaHack 4.0</a>\n            <span>•</span>\n            <a href="https://opensource.guide/" target="_blank">Guia Open Source (GitHub)</a>\n            <span>•</span>\n            <a href="https://github.com/Raoni1984/amazoniahackathon_s3c_docaudit" target="_blank">Repositório GitHub</a>\n        </div>\n        <p>SC3 DocAudit — Protocolo de Cadeia de Custódia e Inteligência Documental para a Amazônia.</p>\n        <p style="font-size: 0.8rem; margin-top: 0.5rem; color: #64748b;">Distribuído sob licença Apache 2.0. Em conformidade com os Arts. 158-A a 158-F do Código de Processo Penal Brasileiro.</p>\n    </footer>\n\n    <script>\n        // SHA-256 via Web Crypto API\n        async function sha256(str) {\n            const buffer = new TextEncoder().encode(str);\n            const digest = await crypto.subtle.digest(\'SHA-256\', buffer);\n            return Array.from(new Uint8Array(digest)).map(b => b.toString(16).padStart(2, \'0\')).join(\'\');\n        }\n\n        async function calculateLiveMerkle() {\n            const l1 = document.getElementById(\'leaf1\').value || \' \';\n            const l2 = document.getElementById(\'leaf2\').value || \' \';\n            const l3 = document.getElementById(\'leaf3\').value || \' \';\n            const l4 = document.getElementById(\'leaf4\').value || \' \';\n\n            const h1 = await sha256(l1);\n            const h2 = await sha256(l2);\n            const h3 = await sha256(l3);\n            const h4 = await sha256(l4);\n\n            const h12 = await sha256(h1 + h2);\n            const h34 = await sha256(h3 + h4);\n            const root = await sha256(h12 + h34);\n\n            document.getElementById(\'node12\').textContent = h12;\n            document.getElementById(\'node34\').textContent = h34;\n            document.getElementById(\'rootNode\').textContent = root;\n        }\n\n        function updateConfidenceSim() {\n            const ocr = parseFloat(document.getElementById(\'ocrSlider\').value) / 100;\n            const syntax = parseFloat(document.getElementById(\'syntaxSlider\').value) / 100;\n            const spatial = parseFloat(document.getElementById(\'spatialSlider\').value) / 100;\n\n            document.getElementById(\'ocrVal\').textContent = ocr.toFixed(2);\n            document.getElementById(\'syntaxVal\').textContent = syntax.toFixed(2);\n            document.getElementById(\'spatialVal\').textContent = spatial.toFixed(2);\n\n            const score = (0.45 * ocr) + (0.35 * syntax) + (0.20 * spatial);\n            const finalScore = Math.min(1.0, Math.max(0.0, score));\n\n            document.getElementById(\'finalScore\').textContent = finalScore.toFixed(3);\n\n            const scoreBox = document.getElementById(\'scoreBox\');\n            const verdict = document.getElementById(\'verdict\');\n\n            if (finalScore >= 0.35) {\n                scoreBox.className = "score-display score-pass";\n                verdict.textContent = "CAMPO EXTRAÍDO COM SUCESSO (CONFIÁVEL)";\n            } else {\n                scoreBox.className = "score-display score-null";\n                verdict.textContent = "ABORTADO: SCORE < 0.35 → ATRIBUÍDO NULL (ANTI-ALUCINAÇÃO)";\n            }\n        }\n\n        // Initialize on load\n        window.addEventListener(\'DOMContentLoaded\', () => {\n            calculateLiveMerkle();\n            updateConfidenceSim();\n        });\n    </script>\n</body>\n</html>\n'
